import math

def is_prime(n):
    """Checks if n is a positive prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def evaluate_product(x, y, z):
    """
    Evaluates P = y^x * z^y * x^z.
    Returns P if it is a positive integer, otherwise returns None.
    """
    try:
        if x == 0 or y == 0 or z == 0:
            return None

        # Standard library pow handles integer exponentiation well for integers.
        term1 = pow(y, x)
        term2 = pow(z, y)
        term3 = pow(x, z)

        P = term1 * term2 * term3
        return P
    except ValueError:
        return None

def find_good_triples(max_coord):
    good_triples = []
    # Search range: [-max_coord, max_coord]
    for x in range(-max_coord, max_coord + 1):
        for y in range(-max_coord, max_coord + 1):
            for z in range(-max_coord, max_coord + 1):
                if x == 0 or y == 0 or z == 0:
                    continue

                P = evaluate_product(x, y, z)

                if P is not None and is_prime(P):
                    S = x**2 + y**2 + z**2
                    # Store (S, x, y, z)
                    good_triples.append((S, x, y, z))

    good_triples.sort()
    return good_triples

